import{_ as e,o as l,c as t,a2 as s}from"./chunks/framework.BXzK3EA4.js";const a="/assets/image-domainZN20251125.Dx-PSPRT.png",n="/assets/image-domainZN2025112501.MDl5sQPp.png",r="/assets/image-domainZN2025112502.TPYOXvS7.png",_=JSON.parse('{"title":"DNS 解析管理","description":"","frontmatter":{"title":"DNS 解析管理"},"headers":[],"relativePath":"ops-knowledge-base/domain/dns-management.md","filePath":"ops-knowledge-base/domain/dns-management.md","lastUpdated":1788259091000}'),i={name:"ops-knowledge-base/domain/dns-management.md"};function d(c,o,g,p,m,h){return l(),t("div",null,[...o[0]||(o[0]=[s('<p>当域名完成开通流程后，为了实现域名与目标服务器、网络服务的关联，让用户能够通过域名顺利访问到对应的内容（如网站、应用服务等），需要在平台后台对域名进行 DNS 解析设置。</p><h2 id="一、域名解析操作流程" tabindex="-1">一、域名解析操作流程 <a class="header-anchor" href="#一、域名解析操作流程" aria-label="Permalink to &quot;一、域名解析操作流程&quot;">​</a></h2><p>域名解析包含两种类型，不同域名需对应采用适配的解析方式，保障解析准确生效。</p><p>操作入口：通过平台导航路径<strong>产品管理****/ 域名与网站 / 域名</strong> 可查看所有域名，右侧点击“<strong>详情</strong>”进入管理界面。</p><hr><h3 id="第一种解析方式" tabindex="-1">第一种解析方式 <a class="header-anchor" href="#第一种解析方式" aria-label="Permalink to &quot;第一种解析方式&quot;">​</a></h3><ol><li><strong>验证说明</strong>：域名开通后需验证，下单后留意查收验证邮件并完成验证，确保域名正常使用。（如没有收到注意下垃圾邮箱）</li><li><strong>一级域名解析</strong>：主机名留空（无需填写内容 ），地址填写目标 IP（如 <code>192.168.1.1</code> ），完成一级域名（如 <code>example.com</code> ）到指定 IP 的解析。</li></ol><ul><li>如果主机名留空，保存报错，可将主机名填写 <code>@</code> 保存。</li></ul><ol start="3"><li><strong>二级域名解析</strong>：主机名填写前缀（如 <code>www</code> ，即 <code>www.example.com</code> ），地址填写目标 IP，实现二级域名解析<img src="'+a+'" alt=""></li><li><strong>域名服务器： 使用默认的域名服务器</strong></li></ol><p><strong><img src="'+n+'" alt=""></strong></p><hr><h3 id="第二种解析方式" tabindex="-1">第二种解析方式 <a class="header-anchor" href="#第二种解析方式" aria-label="Permalink to &quot;第二种解析方式&quot;">​</a></h3><ol><li><strong>一级域名解析</strong>：类型默认为 A ，地址填写目标 IP（如 <code>192.168.1.1</code> ），配置一级域名解析。</li><li><strong>二级域名解析</strong>：主机名填写前缀（如 <code>www</code> ，即 <code>www.example.com</code> ），地址填写目标 IP 。</li></ol><p><img src="'+r+'" alt=""></p><p><strong>以上</strong>填写完成后，点击 <strong>“保存”</strong> 按钮，提交解析配置。配置完全生效时间24h-72h。</p><hr><h3 id="三、dns-记录类型说明" tabindex="-1">三、DNS 记录类型说明 <a class="header-anchor" href="#三、dns-记录类型说明" aria-label="Permalink to &quot;三、DNS 记录类型说明&quot;">​</a></h3><ol><li><p>**A 记录 ：**把域名指向一个 <strong>IPv4 地址</strong></p><ul><li>例：<code>example.com → 192.168.1.10</code></li></ul></li><li><p>**AAAA 记录：**把域名指向一个 <strong>IPv6 地址</strong></p><ul><li>例：<code>example.com → 2001:db8::1</code></li></ul></li><li><p>**CNAME 记录 ：**把一个域名 <strong>别名</strong> 指向另一个域名</p><ul><li>常用于 <code>www.example.com</code> → <code>example.com</code></li><li>注意：CNAME 不能和 A 记录共存</li></ul></li><li><p>**Forward ：**把访问域名的请求 <strong>转发</strong> 到另一个网址（浏览器地址栏会显示跳转后的地址）</p><ul><li>例：将 <code>old-site.com</code> 转发到 <code>https://new-site.com/special-page</code>。</li><li><strong>Stealth Forward</strong>：隐形转发，访问时依然显示原始域名，但内容来自另一个地址（相当于在 iframe 里嵌套）</li></ul></li><li><p>**TXT 记录 ：**存放文本信息，常用于验证域名所有权、设置邮件策略（SPF、DKIM）等</p><ul><li>例：Google / Microsoft 邮箱验证、<code>v=spf1 include:_spf.google.com ~all</code></li></ul></li><li><p>**MX 记录 ：**指定 <strong>邮件服务器</strong>，决定邮件要投递到哪里</p><ul><li>例：<code>example.com MX 10 mail.example.com</code></li></ul></li><li><p><strong>MXE</strong> 记录：让邮件直接投递到某个邮件服务器 IP，而不需要复杂配置。其实就是帮你自动生成一条特殊的 MX 记录。</p></li><li><p><strong>SPF</strong> 记录：SPF 是一种反垃圾邮件机制，属于 TXT 记录的一种。告诉其他邮件服务器“哪些 IP/域名有权限给我的域发邮件”。</p></li><li><p><strong>URL Redirect</strong>：访问某个域名时，<strong>重定向</strong>到另一个网址（常见 301/302 跳转）。</p></li><li><p><strong>URL Frame</strong>：把另一个网站“框架嵌入”当前域名页面里，看起来像是在本域下，但实际是加载另一个站点的内容。</p></li></ol><hr><h2 id="四、注意事项" tabindex="-1">四、注意事项 <a class="header-anchor" href="#四、注意事项" aria-label="Permalink to &quot;四、注意事项&quot;">​</a></h2><ol><li><strong>解析记录准确性</strong>：填写主机名、地址时严格遵循对应规则，错误配置会导致域名无法访问或解析异常。</li><li><strong>生效时间</strong>：DNS 解析配置修改后，需等待全球 DNS 服务器同步，期间可能出现解析不稳定，可通过 <code>nslookup</code>、<code>ping</code> 命令验证解析结果（如 <code>nslookup example.com</code> 查看域名解析的 IP ）。</li><li><strong>域名服务器生效</strong>：修改域名服务器后，旧解析记录会逐步失效，确保新服务器已配置对应解析规则，避免业务中断。</li><li><strong>验证邮件处理</strong>：域名务必及时处理验证邮件，未验证可能导致域名被暂停解析，影响业务访问。</li></ol>',21)])])}const P=e(i,[["render",d]]);export{_ as __pageData,P as default};
